steps.text:
/*
	VIOC_uav_marks.sqf - agregado por tools/vio_build.py (parche uav_friendly_marks; copia configurada, no es del autor de
	la mision). Solo cliente (init.sqf lo lanza con execVM en las maquinas con jugador).

	Drones aliados a la vista (para no derribarlos por error): cada segundo, todos los drones vivos (allUnitsUAV: los de la
	IA, los FPV de ArmaFPV y Drone Warfare, los pedidos con PEDIR: Dron, los de tu bando...) de tu bando o de un bando
	amigo tienen un marcador local en el mapa y el GPS ("Dron aliado", icono NATO de dron con el color del bando) y, con
	VIOC_UAV_FRIENDLY_MARKS = 2, un icono en pantalla con el texto "Dron aliado" hasta VIOC_UM_RANGE3D m. Los enemigos
	no se marcan. Un dron sin tripulacion IA (apagado o recien armado) no tiene bando y tampoco se marca.
	Parametro VIOC_UAV_FRIENDLY_MARKS (0 no, 1 solo mapa, 2 mapa e icono en pantalla).
	Consola (LOCAL EXEC): VIOC_UM_LIST   drones marcados [dron, marcador]
*/
if (!hasInterface) exitWith {};
if (!isNil "VIOC_UM_RUNNING") exitWith {};
VIOC_UM_RUNNING = true;
VIOC_UM_MODE = missionNamespace getVariable ["VIOC_UAV_FRIENDLY_MARKS", 2];
if !(VIOC_UM_MODE isEqualType 0) then {VIOC_UM_MODE = 2};
if (VIOC_UM_MODE <= 0) exitWith {};

VIOC_UM_RANGE3D = 2000;
VIOC_UM_LIST = [];
VIOC_UM_3D = [];
VIOC_UM_N = 0;

//--- [bando] -> [tipo de marcador, color del marcador, color del icono en pantalla]
VIOC_UM_fnc_style = {
	params ["_s"];
	switch (_s) do {
		case west: {["b_uav", "ColorWEST", [0.3, 0.6, 1, 0.9]]};
		case east: {["o_uav", "ColorEAST", [1, 0.35, 0.35, 0.9]]};
		case resistance: {["n_uav", "ColorGUER", [0.35, 0.85, 0.35, 0.9]]};
		default {["n_uav", "ColorUNKNOWN", [0.8, 0.8, 0.8, 0.9]]};
	};
};

VIOC_UM_fnc_friendly = {
	params ["_u"];
	private _s = side _u;
	if !(_s in [west, east, resistance]) exitWith {false};
	private _me = side group player;
	(_s isEqualTo _me) || {(_me getFriend _s) >= 0.6}
};

if (VIOC_UM_MODE >= 2) then {
	addMissionEventHandler ["Draw3D", {
		if (count VIOC_UM_3D == 0) exitWith {};
		private _cam = positionCameraToWorld [0, 0, 0];
		{
			_x params ["_u", "_ico", "_col"];
			if (alive _u) then {
				private _p = ASLToAGL (getPosASLVisual _u);
				private _d = _cam distance _p;
				if (_d < VIOC_UM_RANGE3D && {_d > 20}) then {
					drawIcon3D [_ico, _col, _p vectorAdd [0, 0, 1], 0.8, 0.8, 0, "Dron aliado", 2, 0.032, "PuristaMedium", "center", false];
				};
			};
		} forEach VIOC_UM_3D;
	}];
};

[] spawn {
	waitUntil {sleep 1; !isNull player};
	while {true} do {
		private _now = if (alive player) then {allUnitsUAV select {alive _x && {[_x] call VIOC_UM_fnc_friendly}}} else {[]};
		VIOC_UM_LIST = VIOC_UM_LIST select {
			private _keep = (!isNull (_x select 0)) && {(_x select 0) in _now};
			if (!_keep) then {deleteMarkerLocal (_x select 1)};
			_keep
		};
		private _d3 = [];
		{
			private _u = _x;
			private _st = [side _u] call VIOC_UM_fnc_style;
			private _i = VIOC_UM_LIST findIf {(_x select 0) isEqualTo _u};
			if (_i < 0) then {
				VIOC_UM_N = VIOC_UM_N + 1;
				private _mk = createMarkerLocal [format ["vioc_um_%1", VIOC_UM_N], getPosATL _u];
				_mk setMarkerTypeLocal (_st select 0);
				_mk setMarkerColorLocal (_st select 1);
				_mk setMarkerSizeLocal [0.7, 0.7];
				_mk setMarkerTextLocal "Dron aliado";
				VIOC_UM_LIST pushBack [_u, _mk];
			} else {
				((VIOC_UM_LIST select _i) select 1) setMarkerPosLocal (getPosATL _u);
			};
			_d3 pushBack [_u, getText (configFile >> "CfgMarkers" >> (_st select 0) >> "icon"), _st select 2];
		} forEach _now;
		VIOC_UM_3D = _d3;
		sleep 1;
	};
};

class VIOC_UAV_FRIENDLY_MARKS {
	title = "VIOC: Drones aliados en el mapa (y con icono en pantalla, para no derribarlos)";
	values[] = {0,1,2};
	texts[] = {"No","Solo en el mapa","Mapa e icono en pantalla (hasta 2 km)"};
	default = 2;
};
